<?php
/** Shop grid with data-backed filters, WooCommerce cards, and empty state. */

defined( 'ABSPATH' ) || exit;
$term = is_object( $args['term'] ?? null ) ? $args['term'] : ( function_exists( 'get_queried_object' ) ? get_queried_object() : null );
$initial_category = is_object( $term ) && isset( $term->taxonomy, $term->name ) && 'product_cat' === $term->taxonomy ? (string) $term->name : 'همه';
$products_per_page = class_exists( '\\ErfanSanat\\Theme\\Frontend\\ArchiveConfig' ) ? \ErfanSanat\Theme\Frontend\ArchiveConfig::posts_per_page() : 9;
$column_count = class_exists( '\\ErfanSanat\\Theme\\Frontend\\ArchiveConfig' ) ? \ErfanSanat\Theme\Frontend\ArchiveConfig::columns() : '3';
$grid_columns = array( '1' => 'grid-cols-1', '2' => 'grid-cols-1 sm:grid-cols-2', '3' => 'grid-cols-1 sm:grid-cols-2 xl:grid-cols-3', '4' => 'grid-cols-1 sm:grid-cols-2 xl:grid-cols-4' )[ $column_count ] ?? 'grid-cols-1 sm:grid-cols-2 xl:grid-cols-3';
$visible_filters = class_exists( '\\ErfanSanat\\Theme\\Frontend\\ArchiveConfig' ) ? \ErfanSanat\Theme\Frontend\ArchiveConfig::visible_filters() : array( 'category', 'ip', 'voltage', 'price', 'rating', 'views' );
$query_has_posts = function_exists( 'have_posts' ) ? have_posts() : false;
$ip_values = array( 'IP65', 'IP67', 'IP68' );
$voltage_values = array( '12V DC', '24V DC', '220V AC' );
$filter_id = 'es-product-filters-' . ( is_object( $term ) && isset( $term->term_id ) ? absint( $term->term_id ) : 'shop' );
?>
<section id="archive" data-products-archive="true" data-initial-category="<?php echo esc_attr( $initial_category ); ?>" data-items-per-page="<?php echo esc_attr( (string) $products_per_page ); ?>" class="mx-auto max-w-7xl scroll-mt-24 px-5 py-12 lg:px-8 lg:py-16">
	<div class="mb-6 flex flex-wrap items-end justify-between gap-4"><div><p class="mb-1 text-xs font-bold text-emerald-700">تولیدات عرفان صنعت</p><h2 class="text-2xl font-extrabold text-slate-900">محصولات <?php echo 'همه' !== $initial_category ? esc_html( $initial_category ) : 'فروشگاه'; ?></h2></div><div class="text-xs font-bold text-slate-500">تعداد محصولات: <span data-product-count="true" class="font-black text-emerald-800"><?php echo esc_html( number_format_i18n( (int) ( $GLOBALS['wp_query']->found_posts ?? 0 ) ) ); ?></span></div></div>
	<div class="grid items-start gap-6 lg:grid-cols-3">
		<aside class="hidden space-y-5 rounded-2xl border border-slate-200 bg-white p-5  lg:block" aria-label="فیلتر محصولات">
			<div><label for="<?php echo esc_attr( $filter_id ); ?>-search" class="mb-2 block text-xs font-extrabold text-slate-700">جستجو در محصولات</label><input id="<?php echo esc_attr( $filter_id ); ?>-search" type="search" data-product-search="true" placeholder="نام یا مشخصات محصول" class="w-full rounded-xl border border-slate-200 bg-slate-50/70 py-2.5 pl-3.5 pr-4 text-[13px] font-medium text-slate-800 placeholder:text-slate-400 focus:border-emerald-500 focus:bg-white focus:outline-none"></div>
			<fieldset><legend class="mb-2 text-xs font-extrabold text-slate-700">روش خرید</legend><div class="grid gap-2 text-xs text-slate-700"><?php foreach ( array( 'all' => 'همه محصولات', 'online' => 'خرید آنلاین', 'call' => 'استعلام قیمت' ) as $mode => $label ) : ?><label class="flex items-center gap-2"><input type="radio" name="<?php echo esc_attr( $filter_id ); ?>-purchase" data-product-purchase-mode="<?php echo esc_attr( $mode ); ?>" value="<?php echo esc_attr( $mode ); ?>" <?php checked( 'all', $mode ); ?> class="h-4 w-4 accent-emerald-700"><span><?php echo esc_html( $label ); ?></span></label><?php endforeach; ?></div></fieldset>
			<?php if ( in_array( 'price', $visible_filters, true ) ) : ?><div><label for="<?php echo esc_attr( $filter_id ); ?>-price" class="mb-2 block text-xs font-extrabold text-slate-700">حداکثر قیمت</label><input id="<?php echo esc_attr( $filter_id ); ?>-price" type="range" min="0" max="3000000" value="3000000" data-product-price-range="true" class="h-2 w-full cursor-pointer appearance-none rounded-lg bg-emerald-100 accent-emerald-700"><span data-product-price-label="true" class="mt-2 block text-xs font-semibold text-slate-500">تا ۳٬۰۰۰٬۰۰۰</span></div><?php endif; ?>
			<?php if ( in_array( 'ip', $visible_filters, true ) ) : ?><fieldset><legend class="mb-2 text-xs font-extrabold text-slate-700">درجه حفاظت</legend><div class="grid gap-2 text-xs text-slate-600"><?php foreach ( $ip_values as $ip ) : ?><label class="flex items-center gap-2"><input type="checkbox" data-product-ip-filter="<?php echo esc_attr( $ip ); ?>" value="<?php echo esc_attr( $ip ); ?>" class="h-4 w-4 accent-emerald-700"><span><?php echo esc_html( $ip ); ?></span></label><?php endforeach; ?></div></fieldset><?php endif; ?>
			<?php if ( in_array( 'voltage', $visible_filters, true ) ) : ?><fieldset><legend class="mb-2 text-xs font-extrabold text-slate-700">ولتاژ ورودی</legend><div class="grid gap-2 text-xs text-slate-600"><?php foreach ( $voltage_values as $voltage ) : ?><label class="flex items-center gap-2"><input type="checkbox" data-product-voltage-filter="<?php echo esc_attr( $voltage ); ?>" value="<?php echo esc_attr( $voltage ); ?>" class="h-4 w-4 accent-emerald-700"><span><?php echo esc_html( $voltage ); ?></span></label><?php endforeach; ?></div></fieldset><?php endif; ?>
		</aside>
		<div class="min-w-0 lg:col-span-2">
			<div class="mb-5 flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-slate-200/90 bg-white px-4 py-3 shadow-2xs"><div class="flex items-center gap-2"><button type="button" data-archive-drawer-open="true" class="inline-flex items-center gap-2 rounded-xl bg-emerald-700 px-3.5 py-2 text-[12px] font-extrabold text-white shadow-xs transition-colors hover:bg-emerald-800 lg:hidden">فیلترها</button><span class="text-xs text-slate-500">نمایش <span data-product-count="true" class="font-black text-emerald-800"><?php echo esc_html( number_format_i18n( (int) ( $GLOBALS['wp_query']->found_posts ?? 0 ) ) ); ?></span> محصول</span></div><label class="flex items-center gap-2 text-xs font-bold text-slate-600"><span>مرتب‌سازی:</span><select data-product-sort="true" class="bg-transparent text-[12px] font-extrabold text-slate-800 focus:outline-none cursor-pointer"><option value="popular">پربازدیدترین</option><option value="rating">بالاترین امتیاز</option><option value="price-asc">ارزان‌ترین</option><option value="price-desc">گران‌ترین</option></select></label></div>
			<ul data-product-grid="true" class="grid gap-6 <?php echo esc_attr( $grid_columns ); ?>">
				<?php if ( have_posts() ) : while ( have_posts() ) : the_post(); global $product; $product = function_exists( 'wc_get_product' ) ? wc_get_product( get_the_ID() ) : null; if ( ! $product ) { continue; } if ( function_exists( 'wc_get_template_part' ) ) { wc_get_template_part( 'content', 'product' ); } else { get_template_part( 'woocommerce/content', 'product' ); } endwhile; else : ?><li class="hidden" aria-hidden="true"></li><?php endif; ?>
			</ul>
			<div data-product-empty="true" class="<?php echo $query_has_posts ? 'hidden' : 'block'; ?> rounded-2xl border border-dashed border-slate-300 bg-slate-50/70 py-16 text-center"><h3 class="text-base font-extrabold text-slate-800">محصولی پیدا نشد</h3><p class="mt-2 text-sm text-slate-500">فیلترها را تغییر دهید یا دسته دیگری را انتخاب کنید.</p></div>
			<?php if ( function_exists( 'woocommerce_pagination' ) ) { woocommerce_pagination(); } ?>
		</div>
	</div>
	<div data-archive-drawer="true" class="hidden fixed inset-0 z-50 items-end justify-center bg-slate-950/60 p-0 backdrop-blur-xs sm:items-center sm:p-4 lg:hidden" role="dialog" aria-modal="true" aria-label="فیلتر و دسته‌بندی محصولات"><div data-archive-drawer-backdrop="true" class="absolute inset-0"></div><div class="relative z-10 max-h-[90dvh] w-full overflow-y-auto rounded-t-[2rem] bg-white p-5 max-w-lg sm:rounded-[2rem]"><div class="mb-5 flex items-center justify-between"><h3 class="text-base font-extrabold text-slate-900">فیلتر محصولات</h3><button type="button" data-archive-drawer-close="true" aria-label="بستن پنجره فیلتر" class="grid h-9 w-9 place-items-center rounded-xl border border-slate-200 text-slate-500 transition-colors hover:bg-slate-100 hover:text-slate-800">×</button></div><label for="<?php echo esc_attr( $filter_id ); ?>-modal-search" class="mb-2 block text-xs font-extrabold text-slate-700">جستجو</label><input id="<?php echo esc_attr( $filter_id ); ?>-modal-search" type="search" data-product-search="true" placeholder="نام یا مشخصات محصول" class="mb-5 w-full rounded-xl border border-slate-200 bg-slate-50 py-2.5 px-3.5 text-[13px] font-medium text-slate-800 focus:border-emerald-500 focus:outline-none"><fieldset class="mb-5"><legend class="mb-2 text-xs font-extrabold text-slate-700">روش خرید</legend><div class="grid grid-cols-3 gap-2"><?php foreach ( array( 'all' => 'همه', 'online' => 'خرید آنلاین', 'call' => 'استعلام' ) as $mode => $label ) : ?><label class="rounded-xl border border-slate-200 bg-slate-50 py-2.5 text-center text-[12px] font-extrabold text-slate-700"><input type="radio" name="<?php echo esc_attr( $filter_id ); ?>-purchase-modal" data-product-purchase-mode="<?php echo esc_attr( $mode ); ?>" value="<?php echo esc_attr( $mode ); ?>" <?php checked( 'all', $mode ); ?>><span><?php echo esc_html( $label ); ?></span></label><?php endforeach; ?></div></fieldset><button type="button" data-archive-drawer-close="true" class="flex-1 rounded-xl bg-emerald-700 py-3 text-[13px] font-black text-white shadow-sm transition-colors hover:bg-emerald-800">اعمال فیلترها</button></div></div>
</section>
